-- Produtividade da Indústria · Tela 1 (Mapa do fluxo) — "?" (RD-95) dos campos, filtros e ações.
-- ADITIVA: só INSERT em erp_ajuda_campo (ON CONFLICT DO NOTHING). Textos em linguagem do usuário, editáveis sem deploy.
-- Rota /dashboard/produtividade/mapa (PR B). vertical 'industria' (igual aos "?" do Apontamento).

INSERT INTO public.erp_ajuda_campo (chave, grupo, rotulo, o_que_preencher, para_que_serve, exemplo, erro_comum, ordem, rota, vertical, status)
SELECT v.chave, v.grupo, v.rotulo, v.o_que, v.para_que, v.exemplo, v.erro, v.ordem, '/dashboard/produtividade/mapa', 'industria', 'publicado'
FROM (VALUES
 ('prod.mapa.planta', 'Topo', 'Planta', 'Escolha a planta (unidade industrial) cujo fluxo você quer ver ou montar.', 'O mapa é por planta: cada unidade tem suas raias e postos.', 'Planta Matriz · Planta Filial', 'Montar o fluxo na planta errada.', 1),
 ('prod.mapa.modelo', 'Começar', 'Modelo', 'Escolha um modelo pronto do seu segmento para começar; depois edite tudo. Opcional.', 'Adianta o cadastro com raias e atividades típicas (ex.: abate de bovinos). É só um ponto de partida.', 'Abate de bovinos', 'Achar que o modelo é fixo: tudo é editável e você pode começar do zero.', 2),
 ('prod.mapa.nova_raia', 'Ações', 'Nova raia', 'Toque para criar uma etapa do fluxo (raia). Depois dê o nome e adicione as atividades.', 'Cada raia é um trecho do caminho (ex.: Abate, Desossa). A saída de uma entra na próxima.', 'Desossa', 'Criar uma raia por posto: raia é o trecho, não o posto.', 3),
 ('prod.mapa.raia_nome', 'Raia', 'Nome da raia', 'Nome do trecho do fluxo, como a equipe chama.', 'Identifica a etapa no mapa e nos relatórios.', 'Desossa', 'Deixar "Nova raia" sem renomear.', 4),
 ('prod.mapa.raia_direcao', 'Raia', 'Direção', 'Desmontagem (uma entrada vira várias saídas, ex.: carcaça → cortes) ou Montagem (vários componentes viram um produto). Hoje o cálculo é de desmontagem.', 'Define como o custo caminha: na desmontagem o custo da entrada é rateado entre as saídas.', 'Desmontagem', 'Marcar Montagem numa linha de corte — é desmontagem.', 5),
 ('prod.mapa.raia_mover', 'Raia', 'Mover raia', 'Use as setas para pôr as raias na ordem real do processo (de cima para baixo).', 'A ordem das raias é o caminho do produto, da recepção à câmara final.', 'Abate acima de Desossa.', 'Deixar fora de ordem: o fluxo fica confuso.', 6),
 ('prod.mapa.raia_excluir', 'Raia', 'Excluir raia', 'Toque, informe o motivo e confirme. A raia e suas atividades saem do mapa, mas o registro fica guardado.', 'Remove uma raia criada por engano sem perder o rastro (quem e quando).', 'Motivo: "Raia duplicada".', 'Excluir para "esconder": prefira reordenar ou corrigir.', 7),
 ('prod.mapa.entra_sai', 'Raia', 'Entra / Sai', 'O que ENTRA e o que SAI da raia vem do cadastro de estrutura (origem → saída, com rendimento %).', 'Liga uma raia à próxima: a saída de uma é a entrada da seguinte. Mostra o rendimento esperado de cada saída.', 'Entra: Carcaça resfriada → Sai: Coxão mole (12%), osso, gordura.', 'Esperar preenchimento aqui: as saídas vêm da estrutura do produto.', 8),
 ('prod.mapa.atividade_nome', 'Atividade', 'Atividade', 'Nome da tarefa feita na raia.', 'Cada atividade acontece num posto e tem seu tempo e pessoas.', 'Desossa de dianteiro', 'Repetir o nome do posto: descreva a tarefa.', 9),
 ('prod.mapa.atividade_tipo', 'Atividade', 'Tipo', 'Como a atividade é feita: Manual, Misto (pessoa + equipamento) ou Equipamento.', 'Ajuda a entender onde o ritmo depende de gente e onde depende de máquina.', 'Manual', 'Marcar Equipamento numa tarefa que é manual.', 10),
 ('prod.mapa.atividade_tempo', 'Atividade', 'Tempo por ciclo (s)', 'Quantos segundos leva um ciclo da atividade (uma peça, um animal, um lote). Deixe em branco se ainda não mediu.', 'Serve para calcular a capacidade por hora (3600 ÷ tempo × pessoas). Em branco = a medir, nunca zero.', '120', 'Pôr 0 quando não sabe: deixe em branco (a medir).', 11),
 ('prod.mapa.atividade_pessoas', 'Atividade', 'Pessoas', 'Quantas pessoas trabalham nessa atividade ao mesmo tempo.', 'Multiplica a capacidade do posto e entra no custo de mão de obra.', '8', 'Contar o turno inteiro: conte só quem faz esta atividade.', 12),
 ('prod.mapa.atividade_unidade', 'Atividade', 'Unidade', 'A unidade em que a atividade mede a produção (kg, peça, cabeça, m³, arroba…). Livre.', 'O indicador de produtividade usa a unidade do produto (kg/h, peça/h, cabeça/h).', 'kg', 'Misturar unidades na mesma raia sem necessidade.', 13),
 ('prod.mapa.atividade_posto', 'Atividade', 'Posto', 'O posto onde a atividade acontece (criado junto com a atividade). Edite o posto na tela Postos.', 'Liga a atividade ao posto, que carrega pessoas, capacidade e custo.', 'F08', 'Esperar trocar o posto aqui: isso é feito na tela Postos.', 14),
 ('prod.mapa.nova_atividade', 'Atividade', 'Nova atividade', 'Toque para adicionar uma atividade nesta raia. Um posto é criado para ela.', 'Monta a sequência de tarefas dentro da raia.', 'Sangria, depois Esfola.', 'Criar atividades fora de ordem: use as setas para ordenar.', 15),
 ('prod.mapa.atividade_mover', 'Atividade', 'Mover atividade', 'Use as setas para ordenar as atividades dentro da raia (e, no futuro, movê-las entre raias).', 'A ordem reflete a sequência real do trabalho na raia.', 'Insensibilização antes da Sangria.', 'Deixar fora da ordem do processo.', 16),
 ('prod.mapa.atividade_excluir', 'Atividade', 'Excluir atividade', 'Toque, informe o motivo e confirme. A atividade sai da raia, com registro de quem e quando.', 'Remove uma atividade criada por engano sem perder o histórico.', 'Motivo: "Atividade duplicada".', 'Excluir em vez de corrigir o nome/tempo.', 17)
) AS v(chave, grupo, rotulo, o_que, para_que, exemplo, erro, ordem)
WHERE EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name='erp_ajuda_campo')
ON CONFLICT (chave) DO NOTHING;
